import { useCallback } from "react";
import { useBuilderConnectFlow, } from "../settings/useBuilderStatus.js";
const DEFAULT_TITLE = "Builder connect";
const DEFAULT_DESCRIPTION = "Connect Builder.io for managed model access, browser automation, and workspace identity. Free tier available.";
const DEFAULT_TRACKING_SOURCE = "setup_connections_page";
export function useBuilderConnectCardController({ title = DEFAULT_TITLE, description = DEFAULT_DESCRIPTION, trackingSource = DEFAULT_TRACKING_SOURCE, onConnected, } = {}) {
    const handleConnected = useCallback(({ orgName }) => onConnected?.(orgName), [onConnected]);
    const flow = useBuilderConnectFlow({
        provisionAccount: true,
        trackingSource,
        onConnected: handleConnected,
    });
    const handlePress = useCallback((provisionAccount = false) => flow.start({ provisionAccount }), [flow.start]);
    const status = !flow.hasFetchedStatus
        ? { kind: "checking", label: "Checking" }
        : flow.configured
            ? {
                kind: "connected",
                label: flow.orgName ? `Connected to ${flow.orgName}` : "Connected",
            }
            : { kind: "ready", label: "Ready to connect" };
    return {
        title,
        description,
        status,
        configured: flow.configured,
        pending: flow.connecting,
        error: flow.error,
        orgName: flow.orgName,
        connectFlow: flow,
        action: flow.configured
            ? null
            : {
                label: "Connect Builder.io",
                pending: flow.connecting,
                disabled: flow.connecting,
                onPress: handlePress,
            },
    };
}
